window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d77b0b04c61d39c9"]={"versions": [{"id": "FIG-d77b0b04c61d39c9", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- und Datenflussdiagramm der AUTOSAR-Methodik zur Veranschaulichung des Build- und Konfigurationsprozesses für BSW-Module mit Link-Time-Konfiguration (Link-Time-Bindung). Das Diagramm stellt dar, wie vorkompilierter BSW-Code und separat kompilierte Konfigurationsdaten während der Link-Phase zur ECU-Executable zusammengeführt werden.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\"><strong>Artefakte (Datenobjekte):</strong></p>\n<ul class=\"fig-list\">\n<li><code>Basic Software Module Core Source Code</code> (Kardinalität 1)</li>\n<li><code>Basic Software Module Core Header</code> (Kardinalität 1)</li>\n<li><code>ECU Configuration Values</code> (Kardinalität 1)</li>\n<li><code>Basic Software Module Object Code</code> (Kardinalität 1 als Output, Multiplizität 1..* als Input zum Linker)</li>\n<li><code>BSW Module Configuration Header File</code> (Kardinalität 1)</li>\n<li><code>BSW Module Configuration Data Source Code</code> (Kardinalität 1)</li>\n<li><code>BSW Module Configuration Data Object Code</code> (Kardinalität 1 als Output, Multiplizität 1..* als Input zum Linker)</li>\n<li><code>ECU Executable</code> (Kardinalität 1 als Output des Linkers)</li>\n</ul>\n<p class=\"fig-p\"><strong>Aktivitäten (Prozessschritte):</strong></p>\n<ul class=\"fig-list\">\n<li><code>Compile Unconfigured BSW</code>: Kompiliert Quellcode und Header zu unkonfiguriertem Objektcode.</li>\n<li><code>Generate BSW Configuration Code</code>: Generiert modulspezifische Konfigurations-Header und -Quelldateien aus den ECU-Konfigurationswerten.</li>\n<li><code>Compile BSW Configuration Data</code>: Kompiliert die generierten Konfigurationsdateien zusammen mit dem Modul-Header zu Konfigurations-Objektcode.</li>\n<li><code>Link ECU Code during Link Time Configuration</code>: Bindet die BSW-Objektdateien und Konfigurations-Objektdateien zur finalen ECU-Executable.</li>\n</ul>\n<p class=\"fig-p\">Alle Kanten sind gerichtet und mit Stereotypen (<code>«input»</code>, <code>«output»</code>) sowie Kardinalitäten/Multiplizitäten (<code>1</code>, <code>1..*</code>) annotiert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Generierung der Konfigurationsdateien:</strong> <code>Generate BSW Configuration Code</code> konsumiert die <code>ECU Configuration Values</code> [1] und erzeugt die <code>BSW Module Configuration Header File</code> [1] sowie den <code>BSW Module Configuration Data Source Code</code> [1].</li>\n<li><strong>Kompilierung des Kern-BSW-Codes:</strong> Unabhängig von den Konfigurationswerten liest <code>Compile Unconfigured BSW</code> den <code>Basic Software Module Core Source Code</code> [1] und den <code>Basic Software Module Core Header</code> [1] ein und erzeugt den <code>Basic Software Module Object Code</code> [1].</li>\n<li><strong>Kompilierung der Konfigurationsdaten:</strong> <code>Compile BSW Configuration Data</code> liest den <code>Basic Software Module Core Header</code> [1], die generierte <code>BSW Module Configuration Header File</code> [1] und den generierten <code>BSW Module Configuration Data Source Code</code> [1] ein und erzeugt den <code>BSW Module Configuration Data Object Code</code> [1].</li>\n<li><strong>Link-Vorgang:</strong> <code>Link ECU Code during Link Time Configuration</code> nimmt mindestens ein <code>Basic Software Module Object Code</code> [1..<em>] und mindestens ein <code>BSW Module Configuration Data Object Code</code> [1..</em>] entgegen und linkt diese zur <code>ECU Executable</code> [1].</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm verdeutlicht das Entkopplungsprinzip der Link-Time-Konfiguration in AUTOSAR: Der generische Quellcode des BSW-Moduls (<code>Basic Software Module Core Source Code</code>) bleibt unabhängig von konkreten ECU-Konfigurationswerten kompilierbar, wodurch BSW-Module als vorkompilierter Objektcode ausgeliefert werden können. Die systemspezifische Ausprägung erfolgt über separate Konfigurationsdatenstrukturen, die erst im Link-Schritt gebunden werden. Tool-Hersteller und Integratoren müssen sicherstellen, dass die generierten Konfigurations-Header und -Objektdateien binärkompatibel zu den Annahmen des vorkompilierten Kern-Objektcodes sind.</p>"}, {"id": "FIG-e7969b4bd4d5b779", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- und Datenflussdiagramm der AUTOSAR-Methodik zur Veranschaulichung des Build- und Konfigurationsprozesses für BSW-Module mit Link-Time-Konfiguration (Link-Time-Bindung). Das Diagramm stellt dar, wie vorkompilierter BSW-Code und separat kompilierte Konfigurationsdaten während der Link-Phase zur ECU-Executable zusammengeführt werden.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\"><strong>Artefakte (Datenobjekte):</strong></p>\n<ul class=\"fig-list\">\n<li><code>Basic Software Module Core Source Code</code> (Kardinalität 1)</li>\n<li><code>Basic Software Module Core Header</code> (Kardinalität 1)</li>\n<li><code>ECU Configuration Values</code> (Kardinalität 1)</li>\n<li><code>Basic Software Module Object Code</code> (Kardinalität 1 als Output, Multiplizität 1..* als Input zum Linker)</li>\n<li><code>BSW Module Configuration Header File</code> (Kardinalität 1)</li>\n<li><code>BSW Module Configuration Data Source Code</code> (Kardinalität 1)</li>\n<li><code>BSW Module Configuration Data Object Code</code> (Kardinalität 1 als Output, Multiplizität 1..* als Input zum Linker)</li>\n<li><code>ECU Executable</code> (Kardinalität 1 als Output des Linkers)</li>\n</ul>\n<p class=\"fig-p\"><strong>Aktivitäten (Prozessschritte):</strong></p>\n<ul class=\"fig-list\">\n<li><code>Compile Unconfigured BSW</code>: Kompiliert Quellcode und Header zu unkonfiguriertem Objektcode.</li>\n<li><code>Generate BSW Configuration Code</code>: Generiert modulspezifische Konfigurations-Header und -Quelldateien aus den ECU-Konfigurationswerten.</li>\n<li><code>Compile BSW Configuration Data</code>: Kompiliert die generierten Konfigurationsdateien zusammen mit dem Modul-Header zu Konfigurations-Objektcode.</li>\n<li><code>Link ECU Code during Link Time Configuration</code>: Bindet die BSW-Objektdateien und Konfigurations-Objektdateien zur finalen ECU-Executable.</li>\n</ul>\n<p class=\"fig-p\">Alle Kanten sind gerichtet und mit Stereotypen (<code>«input»</code>, <code>«output»</code>) sowie Kardinalitäten/Multiplizitäten (<code>1</code>, <code>1..*</code>) annotiert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Generierung der Konfigurationsdateien:</strong> <code>Generate BSW Configuration Code</code> konsumiert die <code>ECU Configuration Values</code> [1] und erzeugt die <code>BSW Module Configuration Header File</code> [1] sowie den <code>BSW Module Configuration Data Source Code</code> [1].</li>\n<li><strong>Kompilierung des Kern-BSW-Codes:</strong> Unabhängig von den Konfigurationswerten liest <code>Compile Unconfigured BSW</code> den <code>Basic Software Module Core Source Code</code> [1] und den <code>Basic Software Module Core Header</code> [1] ein und erzeugt den <code>Basic Software Module Object Code</code> [1].</li>\n<li><strong>Kompilierung der Konfigurationsdaten:</strong> <code>Compile BSW Configuration Data</code> liest den <code>Basic Software Module Core Header</code> [1], die generierte <code>BSW Module Configuration Header File</code> [1] und den generierten <code>BSW Module Configuration Data Source Code</code> [1] ein und erzeugt den <code>BSW Module Configuration Data Object Code</code> [1].</li>\n<li><strong>Link-Vorgang:</strong> <code>Link ECU Code during Link Time Configuration</code> nimmt mindestens ein <code>Basic Software Module Object Code</code> [1..<em>] und mindestens ein <code>BSW Module Configuration Data Object Code</code> [1..</em>] entgegen und linkt diese zur <code>ECU Executable</code> [1].</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm verdeutlicht das Entkopplungsprinzip der Link-Time-Konfiguration in AUTOSAR: Der generische Quellcode des BSW-Moduls (<code>Basic Software Module Core Source Code</code>) bleibt unabhängig von konkreten ECU-Konfigurationswerten kompilierbar, wodurch BSW-Module als vorkompilierter Objektcode ausgeliefert werden können. Die systemspezifische Ausprägung erfolgt über separate Konfigurationsdatenstrukturen, die erst im Link-Schritt gebunden werden. Tool-Hersteller und Integratoren müssen sicherstellen, dass die generierten Konfigurations-Header und -Objektdateien binärkompatibel zu den Annahmen des vorkompilierten Kern-Objektcodes sind.</p>"}], "trans": [{"from": "FIG-d77b0b04c61d39c9", "to": "FIG-e7969b4bd4d5b779", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
